function renderVenn(a,b,r){
  const venn=document.getElementById("venn");
  const legend=document.getElementById("legend");
  let html="", legendHtml="", sub="", badge="", interpretation="";

  if(r.relationship==="PARTIAL_OVERLAP"){
    html += circle(a.name,"a","left:85px;top:20px;width:310px;height:310px","left:54px;top:42px",r.onlyA.join("<br>"),"left:22px;top:112px;width:150px",`${a.name.toUpperCase()} ONLY`);
    html += circle(b.name,"b","left:305px;top:20px;width:310px;height:310px","right:54px;top:42px",r.onlyB.join("<br>"),"right:22px;top:112px;width:150px",`${b.name.toUpperCase()} ONLY`);
    html += `<div class="overlap" style="left:280px;top:118px;width:140px"><b>SHARED</b><strong>${r.shared.join("<br>")}</strong></div>`;
    legendHtml=`<div>${a.name.toUpperCase()} ONLY</div><div>SHARED</div><div>${b.name.toUpperCase()} ONLY</div>`;
    badge="PARTIAL OVERLAP";
    sub="Some meanings are confirmed as shared, while others remain unmatched in the current model.";
    interpretation=`<b>Details:</b> the concepts are related, but they are not interchangeable.`;
  }

  if(r.relationship==="B_SUBSET_A"){
    // B's implication set is fully contained in A's implication set.
    html += circle(
      a.name,"a",
      "left:155px;top:15px;width:390px;height:310px",
      "left:58px;top:38px",
      r.onlyA.join("<br>"),
      "left:24px;top:126px;width:135px",
      `${a.name.toUpperCase()} ONLY`
    );
    html += circle(
      b.name,"b",
      "left:315px;top:82px;width:190px;height:190px",
      "left:42px;top:30px",
      r.shared.join("<br>"),
      "left:20px;top:76px;width:150px",
      "SHARED"
    );
    html += `<div class="overlap" style="left:285px;top:274px;width:178px"><b>${b.name.toUpperCase()} ONLY</b><strong>None</strong></div>`;
    legendHtml=`<div>${a.name.toUpperCase()} ONLY</div><div>SHARED</div><div>${b.name.toUpperCase()} ONLY: NONE</div>`;
    badge="CONTAINMENT";
    sub=`Everything implied by ${b.name} is also implied by ${a.name}; ${a.name} adds additional meanings.`;
    interpretation=`<b>Details:</b> ${a.name} is the stronger concept: it includes every implication of ${b.name}, plus more.`;
  }

  if(r.relationship==="A_SUBSET_B"){
    // A's implication set is fully contained in B's implication set.
    // The inner circle is therefore entirely shared; B's extra meanings live in the outer-only region.
    html += circle(
      b.name,"b",
      "left:155px;top:15px;width:390px;height:310px",
      "right:58px;top:38px",
      r.onlyB.join("<br>"),
      "right:24px;top:126px;width:135px",
      `${b.name.toUpperCase()} ONLY`
    );
    html += circle(
      a.name,"a",
      "left:195px;top:82px;width:190px;height:190px",
      "left:42px;top:30px",
      r.shared.join("<br>"),
      "left:20px;top:76px;width:150px",
      "SHARED"
    );
    html += `<div class="overlap" style="left:238px;top:274px;width:178px"><b>${a.name.toUpperCase()} ONLY</b><strong>None</strong></div>`;
    legendHtml=`<div>${a.name.toUpperCase()} ONLY: NONE</div><div>SHARED</div><div>${b.name.toUpperCase()} ONLY</div>`;
    badge="CONTAINMENT";
    sub=`Everything implied by ${a.name} is also implied by ${b.name}; ${b.name} adds additional meanings.`;
    interpretation=`<b>Details:</b> ${b.name} is the stronger concept: it includes every implication of ${a.name}, plus more.`;
  }

  if(r.relationship==="SAME MEANING"){
    html += circle(a.name,"a","left:195px;top:20px;width:310px;height:310px","left:48px;top:42px","","");
    html += circle(b.name,"b","left:195px;top:20px;width:310px;height:310px;background:rgba(125,143,134,.06)","right:48px;bottom:42px","","");
    html += `<div class="overlap" style="left:270px;top:126px;width:160px"><b>100% SHARED</b><strong>Same meanings</strong></div>`;
    legendHtml=`<div>${a.name.toUpperCase()} ONLY: NONE</div><div>SAME MEANING</div><div>${b.name.toUpperCase()} ONLY: NONE</div>`;
    badge="FULL OVERLAP";
    sub="The concepts imply exactly the same things.";
    interpretation=`<b>Details:</b> the names differ, but the concepts are equivalent in the current model.`;
  }

  if(r.relationship==="DISJOINT"){
    html += circle(a.name,"a","left:45px;top:20px;width:285px;height:285px","left:55px;top:42px",r.onlyA.join("<br>"),"left:35px;top:102px;width:190px",`${a.name.toUpperCase()} ONLY`);
    html += circle(b.name,"b","left:370px;top:20px;width:285px;height:285px","right:55px;top:42px",r.onlyB.join("<br>"),"right:35px;top:102px;width:190px",`${b.name.toUpperCase()} ONLY`);
    html += `<div class="overlap" style="left:284px;top:276px;width:132px"><b>SHARED</b><strong>None</strong></div>`;
    legendHtml=`<div>${a.name.toUpperCase()} ONLY</div><div>NO OVERLAP</div><div>${b.name.toUpperCase()} ONLY</div>`;
    badge="NO OVERLAP";
    sub="The concepts have no meanings in common.";
    interpretation=`<b>Details:</b> these concepts are distinct in the current model.`;
  }

  venn.innerHTML=html;
  legend.innerHTML=legendHtml;
  document.getElementById("relationshipBadge").textContent=badge;
  document.getElementById("relationshipSub").textContent=sub;
}

