  rows.forEach(x=>{
    const isUnknown=x[2]==="No confirmed match" || x[2]==="No confirmed match";
    html += `<div class="row">
      <div>${x[0]==="—"?"—":`<span class="fact-name">${x[0]}</span>${x[1]?`<span class="fact-native">${x[1]}</span>`:""}`}</div>
      <div class="center"><span class="relationship-pill ${isUnknown?"unknown":""}">${x[2]}</span></div>
      <div>${x[3]==="—"?"—":`<span class="fact-name">${x[3]}</span>${x[4]?`<span class="fact-native">${x[4]}</span>`:""}`}</div>
    </div>`;
  });
  document.getElementById("implicationTable").innerHTML=html;
}


function renderMappingEvidence(a,b,r){
  const path=document.getElementById("mappingPath");
  const meta=document.getElementById("mappingMeta");
  const note=document.getElementById("unknownNote");
  const key=`${a.id}:${b.id}`;
  const data={
    "returnable:refundable":["Returns.valid_return_path ↔ Payments.refund_path_available","Same meaning · Confirmed · Reviewed by domain owner","The shared meaning is confirmed by an explicit mapping. Other unmatched meanings have no confirmed match."],
    "refundable:returnable":["Payments.refund_path_available ↔ Returns.valid_return_path","Same meaning · Confirmed · Reviewed by domain owner","The shared meaning is confirmed by an explicit mapping. Other unmatched meanings have no confirmed match."],
    "shipped:delivered":["Fulfillment.left_fulfillment_center → Delivery.left_fulfillment_center","Same meaning · Confirmed · Reviewed by domain owner","Delivered carries the confirmed implication that the package has left fulfillment, and adds a destination guarantee."],
    "delivered:shipped":["Delivery.left_fulfillment_center ← Fulfillment.left_fulfillment_center","Same meaning · Confirmed · Reviewed by domain owner","Delivered carries the confirmed implication that the package has left fulfillment, and adds a destination guarantee."],
    "buyercountry:billingcountry":["Orders.payment_instrument_country ≡ Payments.billing_country","Same meaning · Confirmed · Reviewed by domain owner","The names differ, but an explicit mapping confirms the same payment-instrument country semantics."],
    "billingcountry:buyercountry":["Payments.billing_country ≡ Orders.payment_instrument_country","Same meaning · Confirmed · Reviewed by domain owner","The names differ, but an explicit mapping confirms the same payment-instrument country semantics."]
  };
  const d=data[key];
  if(d){path.textContent=d[0];meta.textContent=d[1];note.textContent=d[2];}
  else{
    path.textContent="No confirmed mapping for this demo pair";
    meta.textContent="Unknown";
    note.textContent="Concept Lens does not infer semantic relationships merely from similar names.";
  }
}

function render(){
  const a=concepts[selectA.value], b=concepts[selectB.value];
  const r=classify(a,b);

  document.getElementById("comparisonTitle").textContent=`${a.name} vs ${b.name}`;
  document.getElementById("ownerA").textContent=a.system.toUpperCase();
  document.getElementById("nameA").textContent=a.name;
  document.getElementById("meaningA").textContent=a.definition;
  document.getElementById("ownerB").textContent=b.system.toUpperCase();
  document.getElementById("nameB").textContent=b.name;
  document.getElementById("meaningB").textContent=b.definition;

  renderVenn(a,b,r);
  renderTable(a,b,r);
  renderMappingEvidence(a,b,r);

  const takeawayMap={
    "returnable:refundable":["Related, but not interchangeable.","Both have a confirmed path for reversing the purchase, but Returnable and Refundable carry different additional meaning."],
    "refundable:returnable":["Related, but not interchangeable.","Both have a confirmed path for reversing the purchase, but Refundable and Returnable carry different additional meaning."],
    "shipped:delivered":["Delivered is more specific.","Delivered includes the confirmed meaning of Shipped and adds that the package reached its destination."],
    "delivered:shipped":["Shipped captures only part of Delivered.","Shipped confirms that the package left fulfillment, but does not establish that it reached its destination."],
    "buyercountry:billingcountry":["Different names, same meaning.","The two systems use different vocabulary, but all modeled meanings are confirmed as equivalent."],
    "billingcountry:buyercountry":["Different names, same meaning.","The two systems use different vocabulary, but all modeled meanings are confirmed as equivalent."]
  };
  const t=takeawayMap[`${a.id}:${b.id}`] || ["Relationship unknown.","Lens does not have enough confirmed relationships to explain this pair."];
  document.getElementById("takeawayTitle").textContent=t[0];
  document.getElementById("takeawayCopy").textContent=t[1];
}

selectA.addEventListener("change",render);
selectB.addEventListener("change",render);

document.getElementById("swapBtn").addEventListener("click",()=>{
  const tmp=selectA.value; selectA.value=selectB.value; selectB.value=tmp; render();
});

document.querySelectorAll(".suggested button").forEach(btn=>{
  btn.addEventListener("click",()=>{
    selectA.value=btn.dataset.a;
    selectB.value=btn.dataset.b;
    render();
  });
});

render();
</script>

<script>
document.addEventListener("click", function(e){
  const btn = e.target.closest(".remove-map");
  if(!btn) return;
  const row = btn.closest(".mapping-row") || btn.closest(".mapping-item") || btn.parentElement.parentElement;
  if(window.confirm("Remove this mapping? Comparisons will no longer use it.")){
    if(row) row.remove();
    const toast = document.getElementById("toast");
    if(toast){ toast.textContent="Mapping removed"; toast.classList.add("show"); setTimeout(()=>toast.classList.remove("show"),1800); }
  }
});
</script>

</body>

