import { Fragment, type CSSProperties } from 'react'

import type { Comparison, Concept } from '../domain/types.ts'
import styles from './RelationshipVenn.module.css'

interface Region {
  label: string
  lines: string[]
  style: CSSProperties
}

interface Circle {
  label: string
  variant: 'variantA' | 'variantB'
  style: CSSProperties
  titleStyle: CSSProperties
  region?: Region
}

interface Overlap {
  label: string
  lines: string[]
  style: CSSProperties
}

interface Layout {
  circles: Circle[]
  overlap: Overlap
}

/**
 * Geometry for each relationship shape, in pixels against the fixed 700x370 canvas.
 * The values are taken from the UX mock; changing them changes the drawing.
 */
function layoutFor(comparison: Comparison, a: Concept, b: Concept): Layout {
  const { shared, onlyA, onlyB } = comparison

  switch (comparison.relationship) {
    case 'PARTIAL_OVERLAP':
      return {
        circles: [
          {
            label: a.name,
            variant: 'variantA',
            style: { left: 85, top: 20, width: 310, height: 310 },
            titleStyle: { left: 54, top: 42 },
            region: {
              label: `${a.name.toUpperCase()} ONLY`,
              lines: onlyA,
              style: { left: 22, top: 112, width: 150 },
            },
          },
          {
            label: b.name,
            variant: 'variantB',
            style: { left: 305, top: 20, width: 310, height: 310 },
            titleStyle: { right: 54, top: 42 },
            region: {
              label: `${b.name.toUpperCase()} ONLY`,
              lines: onlyB,
              style: { right: 22, top: 112, width: 150 },
            },
          },
        ],
