            variant: 'variantB',
            style: { left: 315, top: 82, width: 190, height: 190 },
            titleStyle: { left: 42, top: 30 },
            region: { label: 'SHARED', lines: shared, style: { left: 20, top: 76, width: 150 } },
          },
        ],
        overlap: {
          label: `${b.name.toUpperCase()} ONLY`,
          lines: ['None'],
          style: { left: 285, top: 274, width: 178 },
