import { readFileSync, writeFileSync, appendFileSync } from 'node:fs'
import { render, fireEvent } from '@testing-library/react'
import { JSDOM } from 'jsdom'
import { describe, it } from 'vitest'
import ComparePage from './compare/ComparePage.tsx'

const MOCK = '/Users/shimantikas/Experiments/concept-lens/ui-mock/concept_lens_mock_ui.html'
const OUT = '/tmp/venn.txt'

const PAIRS = [
  ['returnable', 'refundable'],
  ['shipped', 'delivered'],
  ['delivered', 'shipped'],
  ['buyercountry', 'billingcountry'],
  ['returnable', 'delivered'],
]

function normStyle(el) {
  const s = el.getAttribute('style') || ''
  return s
    .split(';')
    .map((d) => d.trim().toLowerCase().replace(/\s+/g, ''))
    .filter(Boolean)
    .sort()
    .join(';')
}

/** Flatten the venn into a comparable list of [tag-ish role, inline style, text]. */
function venn(root, sel) {
  return [...root.querySelectorAll(sel)].map(
    (el) => `${normStyle(el)} :: ${(el.textContent || '').replace(/\s+/g, '')}`,
  )
}

describe('venn geometry', () => {
  it('matches the mock for every relationship shape', () => {
    writeFileSync(OUT, '')
    const html = readFileSync(MOCK, 'utf8')

    for (const [a, b] of PAIRS) {
      const dom = new JSDOM(html, { runScripts: 'dangerously' })
      const doc = dom.window.document
      doc.getElementById('conceptA').value = a
      doc.getElementById('conceptB').value = b
      doc.getElementById('conceptA').dispatchEvent(new dom.window.Event('change'))

      const { container, unmount } = render(<ComparePage />)
      fireEvent.change(container.querySelector('#conceptA'), { target: { value: a } })
      fireEvent.change(container.querySelector('#conceptB'), { target: { value: b } })

      const groups = [
        ['circle', '[class*="_circle_"]', '.circle'],
        ['title', '[class*="_circleTitle_"]', '.circle-title'],
        ['region', '[class*="_only_"]', '.only'],
        ['overlap', '[class*="_overlap_"]', '.overlap'],
      ]

      let lines = [`\n===== ${a} vs ${b} =====`]
      let ok = true
      for (const [name, reactSel, mockSel] of groups) {
        const m = venn(doc.getElementById('venn'), mockSel)
        const r = venn(container, reactSel)
        if (JSON.stringify(m) === JSON.stringify(r)) {
          lines.push(`  ${name.padEnd(8)} MATCH (${m.length})`)
        } else {
          ok = false
          lines.push(`  ${name.padEnd(8)} DIFFER`)
          lines.push(`    mock : ${JSON.stringify(m, null, 1)}`)
          lines.push(`    react: ${JSON.stringify(r, null, 1)}`)
        }
      }
      lines.push(`  => ${ok ? 'IDENTICAL GEOMETRY' : 'MISMATCH'}`)
      appendFileSync(OUT, lines.join('\n') + '\n')
      unmount()
    }
  })
})
