    facts.add(new Fact((String) f.get("id"), (String) f.get("label"), (String) f.get("description")));
  concepts.add(new Concept((String) c.get("id"), (String) c.get("name"), (String) c.get("sourceSystem"),
      (String) c.get("definition"), (Integer) c.get("version"), toInstant(c.get("publishedAt")), facts));
}
List<SemanticMapping> mappings = new ArrayList<>();
for (Map<String,Object> m : (List<Map<String,Object>>) mRoot.get("mappings"))
  mappings.add(new SemanticMapping((String) m.get("id"), (String) m.get("leftFactId"), (String) m.get("rightFactId"),
      MappingType.valueOf((String) m.get("type")), MappingStatus.valueOf((String) m.get("status")),
      (String) m.get("rationale"), (String) m.get("reviewedBy")));

System.out.println("parsed: " + concepts.size() + " concepts, "
    + concepts.stream().mapToInt(c -> c.facts().size()).sum() + " facts, " + mappings.size() + " mappings");

var problems = new ArrayList<String>();
var byFactId = new HashMap<String,String>();
for (Concept c : concepts) for (Fact f : c.facts()) {
  if (byFactId.put(f.id(), c.id()) != null) problems.add("duplicate fact id " + f.id());
  if (!f.id().startsWith(c.id() + ".")) problems.add("fact id not qualified by concept: " + f.id());
  if (f.label() == null || f.description() == null) problems.add("missing label/description: " + f.id());
}
for (SemanticMapping m : mappings) {
  for (String fid : List.of(m.leftFactId(), m.rightFactId()))
    if (!byFactId.containsKey(fid)) problems.add(m.id() + " references unknown fact " + fid);
  if (byFactId.get(m.leftFactId()) != null && Objects.equals(byFactId.get(m.leftFactId()), byFactId.get(m.rightFactId())))
    problems.add(m.id() + " maps a concept to itself");
}
System.out.println("integrity problems: " + (problems.isEmpty() ? "NONE" : problems));

// Derive the concept-level result the way the app will, to check it matches the stated expectation.
String derive(Concept L, Concept R, List<SemanticMapping> ms, Map<String,String> owner) {
  var lMatched = new HashSet<String>(); var rMatched = new HashSet<String>();
  for (SemanticMapping m : ms) {
    if (m.status() != MappingStatus.CONFIRMED) continue;
    String a = m.leftFactId(), b = m.rightFactId();
    if (L.id().equals(owner.get(a)) && R.id().equals(owner.get(b))) { lMatched.add(a); rMatched.add(b); }
    if (L.id().equals(owner.get(b)) && R.id().equals(owner.get(a))) { lMatched.add(b); rMatched.add(a); }
  }
  boolean lAll = lMatched.size() == L.facts().size(), rAll = rMatched.size() == R.facts().size();
  if (lAll && rAll) return "SAME_MEANING";
  if (lAll) return "RIGHT_INCLUDES_LEFT";
  if (rAll) return "LEFT_INCLUDES_RIGHT";
  return "NOT_ESTABLISHED";
}
Map<String,Concept> byId = concepts.stream().collect(Collectors.toMap(Concept::id, c -> c));
record Case(String l, String r, String expected) {}
for (Case k : List.of(
    new Case("returns.returnable", "payments.refundable", "NOT_ESTABLISHED"),
    new Case("fulfillment.shipped", "delivery.delivered", "RIGHT_INCLUDES_LEFT"),
    new Case("orders.buyercountry", "payments.billingcountry", "SAME_MEANING"))) {
