  System.out.printf("%-22s -> %-24s got %-20s %s%n", byId.get(k.l()).name(), byId.get(k.r()).name(),
      got, got.equals(k.expected()) ? "MATCHES EXPECTED" : "*** EXPECTED " + k.expected() + " ***");
}
/exit
