package com.conceptlens.repository;

import java.util.List;
import java.util.Optional;

import com.conceptlens.model.Concept;

/**
 * Read access to the concepts published to Concept Lens.
 *
 * <p>Concepts are owned by their source systems, so this repository deliberately offers no way to
 * create, update or delete one. The single exception is {@link #initialize(List)}, which exists
 * only to seed the store at startup and is not part of the runtime API.
 */
public interface ConceptRepository {

    /** All known concepts, in the order they were published to Concept Lens. */
    List<Concept> findAll();

    /** The concept with this id, or empty if no such concept has been published. */
    Optional<Concept> findById(String id);

    /**
     * Seeds the repository with the published concepts. Called once during application startup.
     *
     * <p>After this call the stored concepts are read-only, and calling it again is an error.
     *
     * @throws IllegalStateException if the repository has already been initialized
     */
    void initialize(List<Concept> concepts);
}
