import { useCallback, useEffect, useState } from 'react'

import { ApiError } from './client.ts'

export interface AsyncState<T> {
  data: T | undefined
  error: string | undefined
  loading: boolean
  /** Re-runs the loader, for use after a change that invalidates the data. */
  reload: () => void
}

function describe(error: unknown): string {
  if (error instanceof ApiError) {
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong'
}

/**
 * Runs an async loader and tracks its outcome.
 *
 * The loader must be stable — wrap it in useCallback — so the effect runs when the request
 * actually changes. Responses that arrive after the inputs changed are discarded, so switching
 * concepts quickly cannot leave an earlier comparison on screen.
 */
export function useAsync<T>(load: () => Promise<T>): AsyncState<T> {
  const [data, setData] = useState<T>()
  const [error, setError] = useState<string>()
  const [loading, setLoading] = useState(true)
  const [attempt, setAttempt] = useState(0)

  const reload = useCallback(() => setAttempt((current) => current + 1), [])

  useEffect(() => {
    let current = true
    setLoading(true)

    load()
      .then((result) => {
        if (current) {
          setData(result)
          setError(undefined)
        }
      })
      .catch((cause: unknown) => {
        if (current) {
          setError(describe(cause))
          setData(undefined)
        }
      })
      .finally(() => {
        if (current) {
          setLoading(false)
        }
      })

    return () => {
      current = false
    }
  }, [load, attempt])

  return { data, error, loading, reload }
}
