── derive
function derive(a,b){
  const aRefs=concepts[a].facts.map(f=>factRef(a,f.id));
  const bRefs=concepts[b].facts.map(f=>factRef(b,f.id));
  const mm=pairMappings(a,b);
  const mappedA=new Set(),mappedB=new Set();

  mm.forEach(m=>{
    [m.left,m.right].forEach(ref=>{
      if(aRefs.includes(ref))mappedA.add(ref);
      if(bRefs.includes(ref))mappedB.add(ref);
    });
  });

  const allA=aRefs.length>0&&mappedA.size===aRefs.length;
  const allB=bRefs.length>0&&mappedB.size===bRefs.length;

  let relationship="NOT_ESTABLISHED";
  if(allA&&allB)relationship="SAME_MEANING";
  else if(allA)relationship="RIGHT_INCLUDES_LEFT";
  else if(allB)relationship="LEFT_INCLUDES_RIGHT";

  return {relationship,mappings:mm};
}

── presentation
function presentation(result){
  const L=concepts[leftId].name,R=concepts[rightId].name,n=result.mappings.length;
  if(result.relationship==="SAME_MEANING") return {
    badge:"SAME MEANING",
    title:`${L} and ${R} have the same confirmed meaning.`,
    copy:"Every modeled fact on both sides has a confirmed semantic match.",
    caption:"Full confirmed semantic equivalence"
  };
  if(result.relationship==="RIGHT_INCLUDES_LEFT") return {
    badge:"CONTAINMENT",
    title:`${R} includes all confirmed meaning of ${L}, plus more.`,
    copy:`Every modeled fact in ${L} has a confirmed match in ${R}. ${R} also has additional unmatched meaning.`,
    caption:`${R} includes ${L}`
  };
  if(result.relationship==="LEFT_INCLUDES_RIGHT") return {
    badge:"CONTAINMENT",
    title:`${L} includes all confirmed meaning of ${R}, plus more.`,
    copy:`Every modeled fact in ${R} has a confirmed match in ${L}. ${L} also has additional unmatched meaning.`,
    caption:`${L} includes ${R}`
  };
  if(n>0) return {
    badge:"PARTIAL SHARED MEANING",
    title:"They share meaning, but the overall relationship is not established.",
    copy:`${L} and ${R} have ${n} confirmed shared ${n===1?"meaning":"meanings"}. Their other facts have no confirmed match.`,
    caption:"Overlap represents confirmed shared meaning"
  };
  return {
    badge:"NOT ESTABLISHED",
    title:"No shared meaning is currently confirmed.",
    copy:`There are no confirmed semantic mappings between ${L} and ${R}. They may still relate; that meaning is currently unknown.`,
    caption:"Separate means no confirmed shared meaning yet"
  };
}

── conceptNeighbors
function conceptNeighbors(){
  const neighbors={};
  Object.keys(concepts).forEach(k=>neighbors[k]=new Set());
  mappings.forEach(m=>{
    const a=resolveFact(m.left).conceptId;
    const b=resolveFact(m.right).conceptId;
    if(a!==b){neighbors[a].add(b);neighbors[b].add(a);}
  });
  return neighbors;
}

── renderRelated
function renderRelated(){
  const neighbors=conceptNeighbors();
  const pairKeys=new Set();
  const pairs=[];

  function addPairs(anchor){
    neighbors[anchor].forEach(other=>{
      if(other===leftId||other===rightId)return;
      const key=`${anchor}|${other}`;
      const reverse=`${other}|${anchor}`;
      if(pairKeys.has(key)||pairKeys.has(reverse))return;
      pairKeys.add(key);
      pairs.push([anchor,other]);
    });
  }

  addPairs(leftId);
  addPairs(rightId);

  $("relatedChips").innerHTML = pairs.length
    ? pairs.map(([a,b])=>`<button class="chip" onclick="setPair('${a}','${b}')">${concepts[a].name} ↔ ${concepts[b].name}</button>`).join("")
    : `<span style="font-size:12px;color:var(--muted)">No other related comparisons in this demo data.</span>`;
}

